# Credential-free source extraction. See docs/SOURCE_MAP.csv.
"""Restore original Q5 Venn geometry and Q7 histogram design, preserving verified data.

The Venn paths are the original June 2026 vector export. The embedded Word CGPS
image uses an older background (n=866; bars differ from the saved final scores),
so its histogram/vertical-marker design is reconstructed using Table 28.
"""
import os
from pathlib import Path
HERE = Path(__file__).resolve().parent
source = (HERE / 'build_figures.py').read_text()
source = source.replace("FIG=OUT/'figures'", "FIG=OUT/'figures_original_panels'")
source = source.replace("f'{stem}_preview.png'", "f'{stem}_original_panels_preview.png'")
source = source.replace("'figure_validation.json'", "'figure_validation_original_panels.json'")
start = source.index('ax=fig.add_axes([.035,.55,.45,.38])')
end = source.index('ax=fig.add_axes([.59,.57,.375,.34])', start)
source = source[:start] + '\n# Preserve the original vector geometry and region colors rather than fitting\n# new circles. Only panel typography is harmonized with the revised figure.\nimport re\nfrom lxml import etree as ET\nfrom matplotlib.path import Path as MPath\nfrom matplotlib.patches import PathPatch\nsvg = ET.parse(str(ROOT/\'supplementary_file_2026-10-09/original_media/original_venn.svg\'))\nns = {\'s\':\'http://www.w3.org/2000/svg\'}\nax=fig.add_axes([.039,.56,.455,.37]); ax.set_aspect(\'equal\'); ax.axis(\'off\')\nfor index in range(2,12):\n el=svg.xpath(f\'//s:g[@id="patch_{index}"]/s:path\',namespaces=ns)[0]\n tokens=re.findall(r\'[MCLz]|[-+]?(?:\\d*\\.\\d+|\\d+)(?:[eE][-+]?\\d+)?\',el.get(\'d\'))\n vertices=[]; codes=[]; k=0\n while k<len(tokens):\n  command=tokens[k]; k+=1\n  if command==\'z\': vertices.append(vertices[0]);codes.append(MPath.CLOSEPOLY);continue\n  count=6 if command==\'C\' else 2\n  values=list(map(float,tokens[k:k+count]));k+=count\n  for j in range(0,count,2):\n   vertices.append((values[j],values[j+1]))\n   codes.append({\'M\':MPath.MOVETO,\'L\':MPath.LINETO,\'C\':MPath.CURVE4}[command])\n style=dict(v.strip().split(\': \') for v in el.get(\'style\').split(\';\'))\n ax.add_patch(PathPatch(MPath(vertices,codes),facecolor=style.get(\'fill\',\'none\'),\n  edgecolor=style.get(\'stroke\',\'none\'),alpha=float(style.get(\'opacity\',\'1\')),\n  linewidth=2.0 if \'stroke\' in style else 0))\nfor x,y,label in [(108,97,\'85\'),(340.7,163.6,\'194\'),(235.1,145.7,\'32\'),\n (118.2,305.4,\'101\'),(129.9,204.3,\'221\'),(242.9,234.3,\'14\'),(211.3,189.3,\'36\')]:\n ax.text(x,y,label,ha=\'center\',va=\'center\',fontsize=14.3,weight=\'bold\',color=\'black\')\nax.set_xlim(26,382);ax.set_ylim(341,58)\ncolors=[\'#E63946\',\'#2A9D8F\',\'#457B9D\']\nfig.legend([Circle((0,0),1,fc=c,alpha=.55) for c in colors],\n [\'APOs (374)\',\'Menopause symptoms (276)\',\'Cognitive / dementia (372)\'],\n loc=\'upper left\',bbox_to_anchor=(.046,.566),frameon=False,fontsize=9,ncol=1,handlelength=1)\n' + source[end:]
source = source.replace('ax=fig.add_axes([.045,.43,.91,.52])', 'ax=fig.add_axes([.045,.51,.91,.45])')
source = source.replace('bbox_to_anchor=(.5,.435)', 'bbox_to_anchor=(.5,.507)')
start = source.index("title(fig,.035,.35,'b','Cancer-disease connectivity')")
end = source.index("save(fig,'Supplementary_Figure_2')", start)
source = source[:start] + "\ntitle(fig,.035,.445,'b','Cancer Gene Proximity Score — compound comparison')\nbg=np.array([r[1] for r in tab(28)['blocks'][1]['rows']]);nz=bg[bg>0]\nassert len(bg)==1000 and len(nz)==868\nax=fig.add_axes([.10,.085,.86,.303])\n# Retain the original Word figure's 0–200 axis, grey 5-score bins, colored\n# vertical compound lines, and dashed yellow mean; use the final saved data.\ncounts,bins,_=ax.hist(nz,bins=np.arange(0,205,5),color='lightgray',edgecolor='gray',lw=.65)\nrs=tab(28)['blocks'][0]['rows']\ncomparison=[('Fezolinetant','#d62728'),('Elinzanetant','#1f77b4'),\n ('Goserelin','#e377c2'),('Letrozole','#9467bd'),('Tamoxifen','#17becf'),\n ('Diethylstilbestrol','#2ca02c')]\nhandles=[Line2D([],[],color='lightgray',lw=6,label='Nonzero random compounds (n=868)')]\nfor name,color in comparison:\n score=next(r[2] for r in rs if r[0]==name)\n # The two zero-score comparators share x=0. A wide blue line with a narrow\n # pink line makes both visible without displacing either value.\n ax.axvline(score,color=color,lw=3.4 if name=='Elinzanetant' else 1.7,zorder=3)\n handles.append(Line2D([],[],color=color,lw=2,label=f'{name} ({score})'))\nax.axvline(nz.mean(),color='#F4CA43',ls='--',lw=1.8,zorder=4)\nhandles.append(Line2D([],[],color='#F4CA43',ls='--',lw=2,label=f'Mean ({nz.mean():.1f})'))\nax.legend(handles=handles,loc='upper right',frameon=False,fontsize=8.9,handlelength=2.4,labelspacing=.4)\nax.set_xlim(-8,205);ax.set_ylim(0,540);ax.set_xticks(np.arange(0,201,25));ax.set_yticks(np.arange(0,501,100))\nax.set_xlabel('Distinct cancer diseases reached',fontsize=10.5)\nax.set_ylabel('Random compounds',fontsize=10.5)\nfor side in ['top','right','bottom','left']:\n ax.spines[side].set_visible(True);ax.spines[side].set_color('black');ax.spines[side].set_linewidth(.7)\nax.tick_params(colors='black',labelsize=10)\nax.xaxis.label.set_color('black');ax.yaxis.label.set_color('black')\nassert int(counts.sum())==868\nwith (FIG/'Supplementary_Figure_2_histogram_bins.csv').open('w') as f:\n w=csv.writer(f);w.writerow(['Bin lower bound (inclusive)','Bin upper bound','Random compounds'])\n w.writerows(zip(bins[:-1],bins[1:],counts.astype(int)))\n" + source[end:]
exec(compile(source, str(HERE / 'build_figures.py'), 'exec'))
